"""Command line entry point: version, compute, converge, replay and help."""
import heapq
import json
import sys

from . import __version__

COMPUTE_USAGE = "usage: python3 -m packet_routing_sim compute TOPOLOGY.json"
CONVERGE_USAGE = "usage: python3 -m packet_routing_sim converge TOPOLOGY.json"
REPLAY_USAGE = (
    "usage: python3 -m packet_routing_sim replay TOPOLOGY.json SCENARIO.json"
)

USAGE = """usage: python3 -m packet_routing_sim <command>

commands:
  version                       print the package version
  compute TOPOLOGY.json         compute shortest-path forwarding tables
                                from a static undirected topology
  converge TOPOLOGY.json        show distance-vector convergence round
                                by round from a static undirected topology
  help                          print this message
"""


def parse_topology(topology):
    """Return (nodes, adjacency) for a validated topology, or None if invalid."""
    if not isinstance(topology, dict):
        return None
    nodes_raw = topology.get("nodes")
    links_raw = topology.get("links")
    if not isinstance(nodes_raw, list) or not isinstance(links_raw, list):
        return None

    nodes = []
    declared = set()
    for node in nodes_raw:
        if not isinstance(node, str) or node == "" or node in declared:
            return None
        declared.add(node)
        nodes.append(node)

    adjacency = {node: {} for node in nodes}
    pairs = set()
    for link in links_raw:
        if not isinstance(link, dict):
            return None
        if "from" not in link or "to" not in link or "metric" not in link:
            return None
        source, target, metric = link["from"], link["to"], link["metric"]
        if not isinstance(source, str) or not isinstance(target, str):
            return None
        if source not in declared or target not in declared:
            return None
        if source == target:
            return None
        if isinstance(metric, bool) or not isinstance(metric, int) or metric <= 0:
            return None
        pair = (source, target) if source < target else (target, source)
        if pair in pairs:
            return None
        pairs.add(pair)
        adjacency[source][target] = metric
        adjacency[target][source] = metric

    return nodes, adjacency


def forwarding_table(source, ordered_nodes, adjacency):
    """Dijkstra from source; ties on total metric break to the smaller first hop."""
    distances = {source: 0}
    next_hops = {}
    # Label is (total metric, first hop name); "" is a sentinel for the source
    # and sorts before any real (necessarily non-empty) node name.
    heap = [(0, "", source)]
    settled = set()
    while heap:
        distance, first_hop, node = heapq.heappop(heap)
        if node in settled:
            continue
        settled.add(node)
        distances[node] = distance
        next_hops[node] = first_hop
        for neighbor in sorted(adjacency[node]):
            if neighbor in settled:
                continue
            metric = adjacency[node][neighbor]
            candidate = distance + metric
            candidate_hop = neighbor if node == source else first_hop
            heapq.heappush(heap, (candidate, candidate_hop, neighbor))

    table = {}
    for destination in ordered_nodes:
        if destination == source:
            table[destination] = {"nextHop": None, "metric": 0}
        elif destination in distances:
            table[destination] = {
                "nextHop": next_hops[destination],
                "metric": distances[destination],
            }
        else:
            table[destination] = {"nextHop": None, "metric": None}
    return table


def load_topology(path):
    """Read and validate the topology at path.

    Returns (nodes, adjacency), or an exit code (2) after reporting the
    matching error if the file cannot be read, parsed, or validated.
    """
    try:
        with open(path, "rb") as stream:
            raw = stream.read()
    except OSError:
        print(f"cannot read topology: {path}", file=sys.stderr)
        return 2

    try:
        topology = json.loads(raw)
    except ValueError:
        print("invalid topology", file=sys.stderr)
        return 2

    parsed = parse_topology(topology)
    if parsed is None:
        print("invalid topology", file=sys.stderr)
        return 2
    return parsed


def run_compute(path):
    parsed = load_topology(path)
    if isinstance(parsed, int):
        return parsed
    nodes, adjacency = parsed

    ordered_nodes = sorted(nodes)
    routers = {
        source: forwarding_table(source, ordered_nodes, adjacency)
        for source in ordered_nodes
    }
    output = json.dumps({"routers": routers}, indent=2, ensure_ascii=False)
    sys.stdout.write(output + "\n")
    return 0


def initial_distance_vectors(ordered_nodes, adjacency):
    """Round 0: each router knows only itself and its directly connected links."""
    vectors = {}
    for router in ordered_nodes:
        table = {}
        for destination in ordered_nodes:
            if destination == router:
                table[destination] = {"nextHop": None, "metric": 0}
            elif destination in adjacency[router]:
                table[destination] = {
                    "nextHop": destination,
                    "metric": adjacency[router][destination],
                }
            else:
                table[destination] = {"nextHop": None, "metric": None}
        vectors[router] = table
    return vectors


def distance_vector_round(previous, ordered_nodes, adjacency):
    """Synchronously update every router from the previous round's advertisements."""
    current = {}
    for router in ordered_nodes:
        table = {}
        for destination in ordered_nodes:
            if destination == router:
                table[destination] = {"nextHop": None, "metric": 0}
                continue
            best_metric = None
            best_hop = None
            for neighbor in sorted(adjacency[router]):
                advertised = previous[neighbor][destination]
                if advertised["metric"] is None:
                    continue
                candidate = adjacency[router][neighbor] + advertised["metric"]
                # Neighbors are iterated in name order, so the first best
                # candidate keeps the smaller next-hop name on ties.
                if best_metric is None or candidate < best_metric:
                    best_metric = candidate
                    best_hop = neighbor
            if best_metric is None:
                table[destination] = {"nextHop": None, "metric": None}
            else:
                table[destination] = {"nextHop": best_hop, "metric": best_metric}
        current[router] = table
    return current


def run_converge(path):
    parsed = load_topology(path)
    if isinstance(parsed, int):
        return parsed
    nodes, adjacency = parsed

    ordered_nodes = sorted(nodes)
    vectors = initial_distance_vectors(ordered_nodes, adjacency)
    rounds = [{"round": 0, "routers": vectors}]
    while True:
        updated = distance_vector_round(vectors, ordered_nodes, adjacency)
        if updated == vectors:
            break
        vectors = updated
        rounds.append({"round": len(rounds), "routers": vectors})

    output = {
        "protocol": "distance-vector",
        "convergenceRound": rounds[-1]["round"],
        "rounds": rounds,
    }
    sys.stdout.write(json.dumps(output, indent=2, ensure_ascii=False) + "\n")
    return 0


def link_pair(source, target):
    """Canonical undirected key for a link endpoint pair."""
    return (source, target) if source < target else (target, source)


def parse_scenario(scenario, nodes, adjacency):
    """Return the validated event list for a scenario, or None if invalid.

    Checks structure, field types, references into the original topology,
    strictly increasing positive integer times, and legal state transitions
    (no repeated disables, no restores of objects that are not disabled).
    """
    if not isinstance(scenario, dict):
        return None
    events_raw = scenario.get("events")
    if not isinstance(events_raw, list):
        return None

    node_set = set(nodes)
    link_pairs = set()
    for source in adjacency:
        for target in adjacency[source]:
            link_pairs.add(link_pair(source, target))

    events = []
    down_nodes = set()
    down_links = set()
    last_time = 0
    for event in events_raw:
        if not isinstance(event, dict):
            return None
        time = event.get("time")
        action = event.get("action")
        if isinstance(time, bool) or not isinstance(time, int):
            return None
        if time <= 0 or time <= last_time:
            return None
        if not isinstance(action, str):
            return None
        if action in ("node-down", "node-up"):
            node = event.get("node")
            if not isinstance(node, str) or node not in node_set:
                return None
            if action == "node-down":
                if node in down_nodes:
                    return None
                down_nodes.add(node)
            else:
                if node not in down_nodes:
                    return None
                down_nodes.discard(node)
        elif action in ("link-down", "link-up"):
            source = event.get("from")
            target = event.get("to")
            if not isinstance(source, str) or not isinstance(target, str):
                return None
            pair = link_pair(source, target)
            if pair not in link_pairs:
                return None
            if action == "link-down":
                if pair in down_links:
                    return None
                down_links.add(pair)
            else:
                if pair not in down_links:
                    return None
                down_links.discard(pair)
        else:
            return None
        events.append(event)
        last_time = time
    return events


def run_replay(topology_path, scenario_path):
    parsed = load_topology(topology_path)
    if isinstance(parsed, int):
        return parsed
    nodes, adjacency = parsed

    try:
        with open(scenario_path, "rb") as stream:
            raw = stream.read()
    except OSError:
        print(f"cannot read scenario: {scenario_path}", file=sys.stderr)
        return 2
    try:
        scenario = json.loads(raw)
    except ValueError:
        print("invalid scenario", file=sys.stderr)
        return 2
    events = parse_scenario(scenario, nodes, adjacency)
    if events is None:
        print("invalid scenario", file=sys.stderr)
        return 2

    ordered_nodes = sorted(nodes)
    down_nodes = set()
    down_links = set()

    def current_routers():
        # A link is usable only while neither endpoint is down and no
        # link-down (not yet matched by a link-up) disabled it.
        active = {node: {} for node in ordered_nodes if node not in down_nodes}
        for source in active:
            for target, metric in adjacency[source].items():
                if target not in active:
                    continue
                if link_pair(source, target) in down_links:
                    continue
                active[source][target] = metric
        routers = {}
        for source in ordered_nodes:
            if source in down_nodes:
                routers[source] = {
                    destination: {"nextHop": None, "metric": None}
                    for destination in ordered_nodes
                }
            else:
                routers[source] = forwarding_table(source, ordered_nodes, active)
        return routers

    timeline = [{"event": None, "routers": current_routers()}]
    for event in events:
        action = event["action"]
        if action == "node-down":
            down_nodes.add(event["node"])
        elif action == "node-up":
            down_nodes.discard(event["node"])
        else:
            pair = link_pair(event["from"], event["to"])
            if action == "link-down":
                down_links.add(pair)
            else:
                down_links.discard(pair)
        timeline.append(
            {"time": event["time"], "event": event, "routers": current_routers()}
        )

    output = {"protocol": "link-state", "timeline": timeline}
    sys.stdout.write(json.dumps(output, indent=2, ensure_ascii=False) + "\n")
    return 0


def main(argv: list[str] | None = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    command = args[0] if args else "help"
    if command == "version":
        print(__version__)
        return 0
    if command == "compute":
        if len(args) != 2:
            print(COMPUTE_USAGE, file=sys.stderr)
            return 2
        return run_compute(args[1])
    if command == "converge":
        if len(args) != 2:
            print(CONVERGE_USAGE, file=sys.stderr)
            return 2
        return run_converge(args[1])
    if command == "replay":
        if len(args) != 3:
            print(REPLAY_USAGE, file=sys.stderr)
            return 2
        return run_replay(args[1], args[2])
    if command in {"help", "-h", "--help"}:
        print(USAGE, end="")
        return 0
    print(f"unknown command: {command}", file=sys.stderr)
    print(USAGE, end="", file=sys.stderr)
    return 2


if __name__ == "__main__":
    raise SystemExit(main())

"""Differential and property tests for the public ``compute``/``converge`` CLI.

These tests exercise only the documented command-line surface
(`python -m packet_routing_sim <command> TOPOLOGY.json`) and never import or
call ``forwarding_table`` / ``distance_vector_round``: every expected value is
either hand-written for a small topology or produced by an independently
written Floyd-Warshall / Bellman-Ford reference in this module, so a defect in
the implementation cannot simultaneously corrupt the answer under test and
the assertion about it.
"""
import json
import os
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[1]

# Run every subprocess under several hash seeds: dict iteration order (and thus
# any accidental dependence on it) must never change the published output.
# PRSIM_TEST_SEEDS="0" restricts the set so local mutation runs stay quick.
HASH_SEEDS = tuple(
    int(seed)
    for seed in os.environ.get("PRSIM_TEST_SEEDS", "0,1,42,987654321").split(",")
)

VERSION = "0.1.0"
COMPUTE_USAGE = "usage: python3 -m packet_routing_sim compute TOPOLOGY.json\n"
CONVERGE_USAGE = "usage: python3 -m packet_routing_sim converge TOPOLOGY.json\n"
REPLAY_USAGE = (
    "usage: python3 -m packet_routing_sim replay TOPOLOGY.json SCENARIO.json\n"
)
USAGE = """usage: python3 -m packet_routing_sim <command>

commands:
  version                       print the package version
  compute TOPOLOGY.json         compute shortest-path forwarding tables
                                from a static undirected topology
  converge TOPOLOGY.json        show distance-vector convergence round
                                by round from a static undirected topology
  help                          print this message
"""


# ---------------------------------------------------------------------------
# CLI invocation and topology helpers
# ---------------------------------------------------------------------------

def link(source, target, metric):
    return {"from": source, "to": target, "metric": metric}


def run_cli(args, seed=0):
    """Invoke the package as a module; return the completed process."""
    env = dict(os.environ)
    env["PYTHONPATH"] = str(REPO_ROOT) + os.pathsep + env.get("PYTHONPATH", "")
    env["PYTHONHASHSEED"] = str(seed)
    return subprocess.run(
        [sys.executable, "-m", "packet_routing_sim", *args],
        cwd=REPO_ROOT,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=60,
    )


def write_topology(directory, topology, name="topology.json"):
    path = Path(directory) / name
    path.write_text(json.dumps(topology), encoding="utf-8")
    return path


def invoke_both(directory, topology, seed=0):
    """Return ((compute_json, compute_bytes), (converge_json, converge_bytes))."""
    path = write_topology(directory, topology)
    compute_proc = run_cli(["compute", str(path)], seed=seed)
    converge_proc = run_cli(["converge", str(path)], seed=seed)
    assert compute_proc.returncode == 0, compute_proc.stderr
    assert converge_proc.returncode == 0, converge_proc.stderr
    assert compute_proc.stderr == b"" and converge_proc.stderr == b""
    return (
        (json.loads(compute_proc.stdout), compute_proc.stdout),
        (json.loads(converge_proc.stdout), converge_proc.stdout),
    )


# ---------------------------------------------------------------------------
# Independent reference implementation (test-side oracle)
# ---------------------------------------------------------------------------

def build_adjacency(topology):
    """Build an undirected adjacency map straight from the declared links."""
    nodes = sorted(topology["nodes"])
    adjacency = {node: {} for node in nodes}
    for edge in topology["links"]:
        a, b, w = edge["from"], edge["to"], edge["metric"]
        adjacency[a][b] = w
        adjacency[b][a] = w
    return nodes, adjacency


def floyd_warshall(nodes, adjacency):
    """All-pairs shortest path lengths, written independently of the SUT."""
    inf = float("inf")
    dist = {i: {j: inf for j in nodes} for i in nodes}
    for node in nodes:
        dist[node][node] = 0
    for a in nodes:
        for b, w in adjacency[a].items():
            # The topology validates at most one link per undirected pair.
            dist[a][b] = w
    for k in nodes:
        dk = dist[k]
        for i in nodes:
            di = dist[i]
            through_base = di[k]
            if through_base == inf:
                continue
            for j in nodes:
                candidate = through_base + dk[j]
                if candidate < di[j]:
                    di[j] = candidate
    return dist


def oracle_tables(topology):
    """Expected {(router, destination): (nextHop, metric)} via Floyd-Warshall.

    On equal total cost the lexicographically smallest direct neighbor wins,
    matching the published tie-break rule.
    """
    nodes, adjacency = build_adjacency(topology)
    dist = floyd_warshall(nodes, adjacency)
    expected = {}
    for source in nodes:
        for dest in nodes:
            if source == dest:
                expected[source, dest] = (None, 0)
                continue
            if dist[source][dest] == float("inf"):
                expected[source, dest] = (None, None)
                continue
            winners = [
                neighbor
                for neighbor in adjacency[source]
                if dist[neighbor][dest] != float("inf")
                and adjacency[source][neighbor] + dist[neighbor][dest]
                == dist[source][dest]
            ]
            hop = min(winners)
            expected[source, dest] = (hop, dist[source][dest])
    return nodes, expected


def normalize(routers):
    """Convert JSON routing tables into {(r, d): (nextHop, metric)} tuples."""
    return {
        (r, d): (entry["nextHop"], entry["metric"])
        for r, row in routers.items()
        for d, entry in row.items()
    }


def synchronous_update(previous, nodes, adjacency):
    """One independent Bellman-Ford synchronous round from a prior snapshot.

    Only the *previous* round's neighbor advertisements are read; nothing from
    the round being computed. Ties keep the smaller neighbor name because
    neighbors are scanned in sorted order with a strict `<` comparison.
    """
    current = {}
    for router in nodes:
        for dest in nodes:
            if dest == router:
                current[router, dest] = (None, 0)
                continue
            best_cost = None
            best_hop = None
            for neighbor in sorted(adjacency[router]):
                advertised_cost = previous[neighbor, dest][1]
                if advertised_cost is None:
                    continue
                cost = adjacency[router][neighbor] + advertised_cost
                if best_cost is None or cost < best_cost:
                    best_cost = cost
                    best_hop = neighbor
            if best_cost is None:
                current[router, dest] = (None, None)
            else:
                current[router, dest] = (best_hop, best_cost)
    return current


def round_zero(nodes, adjacency):
    """The only legal round-0 view: self plus direct links."""
    tables = {}
    for router in nodes:
        for dest in nodes:
            if dest == router:
                tables[router, dest] = (None, 0)
            elif dest in adjacency[router]:
                tables[router, dest] = (dest, adjacency[router][dest])
            else:
                tables[router, dest] = (None, None)
    return tables


# ---------------------------------------------------------------------------
# Fixed, reproducible fixtures
# ---------------------------------------------------------------------------

EMPTY = {"nodes": [], "links": []}

SINGLE = {"nodes": ["solo"], "links": []}

# Two nontrivial components plus a fully isolated node.
COMPONENTS = {
    "nodes": ["a1", "a2", "b1", "b2", "iso"],
    "links": [link("a1", "a2", 2), link("b1", "b2", 5)],
}

CHAIN3 = {
    "nodes": ["A", "B", "C"],
    "links": [link("A", "B", 5), link("B", "C", 7)],
}

CHAIN4 = {
    "nodes": ["A", "B", "C", "D"],
    "links": [link("A", "B", 1), link("B", "C", 2), link("C", "D", 4)],
}

# Weights 1/2/3/4 create genuine equal-cost routes (B<->D costs 5 both ways).
RING = {
    "nodes": ["A", "B", "C", "D"],
    "links": [
        link("A", "B", 1),
        link("B", "C", 2),
        link("C", "D", 3),
        link("D", "A", 4),
    ],
}

# Unit diamond: every A<->D and B<->C route has two equal-cost alternatives.
DIAMOND = {
    "nodes": ["A", "B", "C", "D"],
    "links": [
        link("A", "B", 1),
        link("A", "C", 1),
        link("B", "D", 1),
        link("C", "D", 1),
    ],
}

# Same tie situation with non-unit weights, deliberately declared with nodes
# reversed and links in mixed directions/order: output must not depend on it.
TIECOST = {
    "nodes": ["T", "n2", "n1", "S"],
    "links": [
        link("T", "n2", 3),
        link("n1", "T", 3),
        link("n2", "S", 2),
        link("S", "n1", 2),
    ],
}

# Equal-cost square (both directions around cost 4) plus an isolated node.
SQUARE = {
    "nodes": ["A", "B", "C", "D"],
    "links": [
        link("A", "B", 2),
        link("B", "C", 2),
        link("C", "D", 2),
        link("D", "A", 2),
    ],
}

CHAIN3_WITH_ISOLATE = {
    "nodes": ["A", "B", "C", "Z"],
    "links": [link("A", "B", 5), link("B", "C", 7)],
}

# Hand-computed expected tables for the small topologies. `None`/`None` marks
# an unreachable destination; `None`/0 marks the router's own entry.
def _table(rows):
    return {
        (router, dest): value
        for router, row in rows.items()
        for dest, value in row.items()
    }


HAND_EXPECTED = {
    "single": _table({"solo": {"solo": (None, 0)}}),
    "components": _table(
        {
            "a1": {
                "a1": (None, 0),
                "a2": ("a2", 2),
                "b1": (None, None),
                "b2": (None, None),
                "iso": (None, None),
            },
            "a2": {
                "a1": ("a1", 2),
                "a2": (None, 0),
                "b1": (None, None),
                "b2": (None, None),
                "iso": (None, None),
            },
            "b1": {
                "a1": (None, None),
